import{_ as t,o as a,c as i,a2 as e}from"./chunks/framework.Lq8Lraw_.js";const k=JSON.parse('{"title":"03 三区模型：工作区、暂存区、版本库","description":"","frontmatter":{},"headers":[],"relativePath":"guide/basics/03-three-areas.md","filePath":"guide/basics/03-three-areas.md","lastUpdated":1792671989000}'),n={name:"guide/basics/03-three-areas.md"};function d(l,s,p,o,c,h){return a(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="_03-三区模型-工作区、暂存区、版本库" tabindex="-1">03 三区模型：工作区、暂存区、版本库 <a class="header-anchor" href="#_03-三区模型-工作区、暂存区、版本库" aria-label="Permalink to &quot;03 三区模型：工作区、暂存区、版本库&quot;">​</a></h1><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>能画出工作区、暂存区、本地版本库、远程仓库四层结构及数据流向。</li><li>能说出文件从 untracked 到 committed、再到 modified 的完整状态生命周期。</li><li>能读懂 <code>git status -s</code> 输出中 <code>XY</code> 两列各自的含义。</li><li>能用 <code>git add</code>、<code>git commit</code> 精确控制哪些内容进入下一次提交。</li><li>能编写 <code>.gitignore</code> 规则，并处理已被跟踪但需要忽略的文件。</li></ul><h2 id="四层结构" tabindex="-1">四层结构 <a class="header-anchor" href="#四层结构" aria-label="Permalink to &quot;四层结构&quot;">​</a></h2><p>Git 把代码的流转拆成四个位置。理解它们，绝大多数「为什么提交里多了/少了文件」的问题都能自行定位。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工作区（working tree）      暂存区（index）        本地版本库（repository）      远程仓库（remote）</span></span>
<span class="line"><span>   README.md        --add--&gt;   待提交快照    --commit--&gt;    commit 对象      --push--&gt;   origin/main</span></span>
<span class="line"><span>       ^                         |                            |                              |</span></span>
<span class="line"><span>       |&lt;------ restore ---------|                            |                              |</span></span>
<span class="line"><span>       |&lt;------------------ restore --staged -----------------|                              |</span></span>
<span class="line"><span>       |&lt;------------------------ reset ----------------------|                              |</span></span>
<span class="line"><span>       |                                                                                     |</span></span>
<span class="line"><span>       |&lt;-------------------------------- fetch / pull -------------------------------------|</span></span></code></pre></div><ul><li>工作区：磁盘上能直接编辑的文件。</li><li>暂存区（staging area / index）：一个二进制文件 <code>.git/index</code>，记录「下一次提交要包含什么」。</li><li>本地版本库：<code>.git/objects</code> 中不可变的提交、目录树、文件对象。</li><li>远程仓库：团队共享的另一个完整仓库，通过 <code>origin</code> 等远程名引用。</li></ul><p>暂存区是 Git 区别于许多旧式版本控制的关键设计。它让一次提交可以只包含部分修改，而不是「工作区现在是什么就提交什么」。</p><h2 id="文件状态生命周期" tabindex="-1">文件状态生命周期 <a class="header-anchor" href="#文件状态生命周期" aria-label="Permalink to &quot;文件状态生命周期&quot;">​</a></h2><p>Git 中的文件始终处于以下四种状态之一：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>untracked ──git add──&gt; staged ──git commit──&gt; committed</span></span>
<span class="line"><span>                          ^                       |</span></span>
<span class="line"><span>                          |                       | 修改文件</span></span>
<span class="line"><span>                          └────── git add ────────┘</span></span>
<span class="line"><span>                                  modified</span></span></code></pre></div><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th><code>git status</code> 提示</th></tr></thead><tbody><tr><td>untracked</td><td>新文件，从未被 Git 记录</td><td><code>Untracked files</code></td></tr><tr><td>staged</td><td>修改已写入暂存区，等待提交</td><td><code>Changes to be committed</code></td></tr><tr><td>committed</td><td>已写入本地版本库</td><td><code>nothing to commit, working tree clean</code></td></tr><tr><td>modified</td><td>已跟踪文件在工作区被改动，尚未暂存</td><td><code>Changes not staged for commit</code></td></tr></tbody></table><p>注意：<code>modified</code> 是相对「暂存区中的版本」而言。一个文件可以同时有已暂存和未暂存的修改，此时它在 <code>git status -s</code> 中会显示为 <code>MM</code>。</p><h2 id="读懂-git-status-短格式" tabindex="-1">读懂 git status 短格式 <a class="header-anchor" href="#读懂-git-status-短格式" aria-label="Permalink to &quot;读懂 git status 短格式&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On branch main</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Changes to be committed:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#         modified:   src/app.ts</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Changes not staged for commit:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#         modified:   README.md</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Untracked files:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#         docs/notes.md</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># M  src/app.ts</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  M README.md</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ?? docs/notes.md</span></span></code></pre></div><p>短格式的两个字符 <code>XY</code>：</p><ul><li><code>X</code>：暂存区相对 <code>HEAD</code> 的差异（已暂存的变化）。</li><li><code>Y</code>：工作区相对暂存区的差异（未暂存的变化）。</li><li><code>??</code>：未跟踪文件；<code>!!</code>：被忽略的文件（需 <code>--ignored</code> 才显示）。</li></ul><table tabindex="0"><thead><tr><th>输出</th><th>含义</th></tr></thead><tbody><tr><td><code>??</code></td><td>新文件，未跟踪</td></tr><tr><td><code>A </code></td><td>新文件已暂存</td></tr><tr><td><code> M</code></td><td>已跟踪文件被修改，未暂存</td></tr><tr><td><code>M </code></td><td>修改已暂存</td></tr><tr><td><code>MM</code></td><td>暂存后又改了一次，两部分都存在</td></tr><tr><td><code> D</code></td><td>工作区删除了文件，未暂存</td></tr><tr><td><code>D </code></td><td>删除操作已暂存</td></tr><tr><td><code>R </code></td><td>重命名已暂存</td></tr><tr><td><code>UU</code></td><td>合并冲突，双方都修改了同一区域</td></tr></tbody></table><p>记忆方法：左列看「提交会带上什么」，右列看「还有什么没放进暂存区」。</p><h2 id="状态如何被命令改变" tabindex="-1">状态如何被命令改变 <a class="header-anchor" href="#状态如何被命令改变" aria-label="Permalink to &quot;状态如何被命令改变&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>起点</th><th>终点</th><th>命令</th></tr></thead><tbody><tr><td>暂存新文件/修改</td><td>工作区</td><td>暂存区</td><td><code>git add &lt;path&gt;</code></td></tr><tr><td>暂存已跟踪文件的删除</td><td>工作区</td><td>暂存区</td><td><code>git add -u</code> 或 <code>git rm &lt;path&gt;</code></td></tr><tr><td>生成提交</td><td>暂存区</td><td>本地版本库</td><td><code>git commit -m &quot;...&quot;</code></td></tr><tr><td>撤销暂存</td><td>暂存区</td><td>工作区保持</td><td><code>git restore --staged &lt;path&gt;</code></td></tr><tr><td>丢弃工作区修改</td><td>暂存区</td><td>工作区</td><td><code>git restore &lt;path&gt;</code></td></tr><tr><td>发布提交</td><td>本地版本库</td><td>远程仓库</td><td><code>git push</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hello&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ?? demo.txt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A  demo.txt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;docs: 添加演示文件&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [main 8b1e0d4] docs: 添加演示文件</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  1 file changed, 1 insertion(+)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># （无输出，工作区干净）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;world&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  M demo.txt</span></span></code></pre></div><p><code>git commit</code> 只读取暂存区。提交后再改文件，改动留在工作区，必须再次 <code>git add</code> 才会进入下一次提交。</p><h2 id="gitignore" tabindex="-1">.gitignore <a class="header-anchor" href="#gitignore" aria-label="Permalink to &quot;.gitignore&quot;">​</a></h2><p><code>.gitignore</code> 放在仓库任意目录，规则作用于该目录及其子目录。常见写法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 依赖与构建产物</span></span>
<span class="line"><span>node_modules/</span></span>
<span class="line"><span>dist/</span></span>
<span class="line"><span>build/</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 环境变量与密钥</span></span>
<span class="line"><span>.env</span></span>
<span class="line"><span>.env.*</span></span>
<span class="line"><span>!.env.example</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 日志与临时文件</span></span>
<span class="line"><span>*.log</span></span>
<span class="line"><span>*.tmp</span></span>
<span class="line"><span>.DS_Store</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 只忽略根目录下的 docs 缓存，不影响子目录</span></span>
<span class="line"><span>/docs/.cache/</span></span></code></pre></div><p>语法要点：</p><table tabindex="0"><thead><tr><th>写法</th><th>含义</th></tr></thead><tbody><tr><td><code>dist/</code></td><td>忽略任意层级的 <code>dist</code> 目录</td></tr><tr><td><code>/dist/</code></td><td>只忽略仓库根目录下的 <code>dist</code></td></tr><tr><td><code>*.log</code></td><td>忽略任意层级的日志文件</td></tr><tr><td><code>!important.log</code></td><td>取消忽略，需放在能覆盖前规则的顺序之后</td></tr><tr><td><code>docs/**/*.tmp</code></td><td><code>**</code> 匹配任意层级目录</td></tr></tbody></table><h3 id="已跟踪文件不受-gitignore-影响" tabindex="-1">已跟踪文件不受 .gitignore 影响 <a class="header-anchor" href="#已跟踪文件不受-gitignore-影响" aria-label="Permalink to &quot;已跟踪文件不受 .gitignore 影响&quot;">​</a></h3><p><code>.gitignore</code> 只控制未跟踪文件。一个文件如果曾经被提交，即使后来写进 <code>.gitignore</code>，Git 仍会继续跟踪它的修改。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 从索引中移除，但保留磁盘文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;chore: 停止跟踪本地环境变量文件&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 确认状态</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># D  .env        ← 暂存区记录为删除</span></span></code></pre></div><p>如果 <code>.env</code> 已经推送过，历史中仍然存在敏感信息。此时必须轮换密钥，再视情况用历史改写工具清理；仅删除当前文件并不能让泄露的凭据失效。</p><div class="warning custom-block"><p class="custom-block-title">空目录不会被跟踪</p><p>Git 只跟踪文件。一个目录下的文件全部被忽略时，该目录不会出现在提交中。需要保留结构时，放一个 <code>.gitkeep</code> 并显式 <code>git add</code>。</p></div><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title"><code>git add .</code> 可能把密钥一起提交</p><p><code>.</code> 会递归暂存当前目录下所有未忽略文件，包括 <code>.env</code>、本地数据库、调试配置。养成先 <code>git status -s</code> 再 <code>git add &lt;具体路径&gt;</code> 的习惯；至少确认 <code>.gitignore</code> 已覆盖敏感文件。</p></div><div class="warning custom-block"><p class="custom-block-title"><code>.gitignore</code> 对已暂存文件无效</p><p>文件已经进入暂存区后，再加入 <code>.gitignore</code> 不会自动取消暂存。必须 <code>git restore --staged &lt;file&gt;</code> 或 <code>git rm --cached &lt;file&gt;</code>。</p></div><div class="tip custom-block"><p class="custom-block-title">删除文件用 <code>git rm</code></p><p>直接 <code>rm file</code> 后，<code>git status</code> 会显示 <code> D</code>，仍需 <code>git add -u</code> 才把删除写入暂存区。<code>git rm file</code> 一步完成删除与暂存；只想取消跟踪、保留磁盘文件时用 <code>--cached</code>。</p></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四层结构是工作区、暂存区、本地版本库、远程仓库，<code>add</code>、<code>commit</code>、<code>push</code> 依次推进。</li><li>文件状态按 untracked → staged → committed → modified 循环，暂存区是提交内容的唯一来源。</li><li><code>git status -s</code> 的 <code>X</code> 列表示已暂存变化，<code>Y</code> 列表示未暂存变化。</li><li><code>.gitignore</code> 只影响未跟踪文件，已跟踪文件需要 <code>git rm --cached</code> 才能停止跟踪。</li><li>提交前先看状态，再精确暂存，能避免绝大多数误提交。</li></ul><p>接下来用 <a href="/git-tutorial-site/guide/basics/04-first-commit">04 提交四件套</a> 把这套模型落到日常命令上。</p>`,40)])])}const g=t(n,[["render",d]]);export{k as __pageData,g as default};
